pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        vm.prank(c.Owner());
        (bool success,) = address(c).call(abi.encodeWithSignature("withdraw()"));
        assertTrue(success ? address(c).balance == 0 : true);
    }
}
